INSERT INTO feature VALUES('descent-any-parameter','recursion','Descent on any parameter','structural-recursion','implemented','ordinary',NULL,'The lowering reads the staged position off the body: the parameter the claims'' cases take apart is the fixpoint''s first binder with StructuralDescent, the parameters before it outside and uniform, the ones after it free under the staged lambda; claims on two parameters refused DescentOnSeveralParameters; an unapplied f[<] is the self binder; a parameter before the recursed-on one may vary between calls. A claim under a match on the staged parameter descends on it whatever matches on other parameters stand between, and the staged parameter is the innermost matched one the first call does not pass back unchanged, so a walk consumes a second list alongside the one it descends on. A constructor written as a descent''s argument takes its type from the parameter it fills, as an ordinary call''s does, a uniform parameter that type names standing for itself.','surface-lowering','corpus/model/data/descent.gandr corpus/pathological/data/descent.gandr corpus/model/identity/int-accumulated.gandr crates/surface-lowering/src/lower/native/tests.rs::a_descent_call_s_constructor_argument_takes_its_parameter_s_type_2127 crates/surface-lowering/src/lower/native/tests.rs::a_claim_under_a_match_on_another_parameter_descends_on_the_staged_one_2135','corpus/model/data/descent.gandr','#392 #518');
